"""Shared fixtures for music-lib tests."""
from __future__ import annotations

import shutil
import subprocess

import pytest

#: A minimal valid MPEG frame — enough for EasyMP3/media info to parse.
MP3_FRAME = b"\xff\xfb\x90\x44" + b"\x00" * 413


@pytest.fixture(scope="session")
def ffmpeg() -> bool:
    if shutil.which("ffmpeg") is None:
        pytest.skip("ffmpeg не установлен")
    return True


@pytest.fixture
def audio_files(tmp_path, ffmpeg) -> dict[str, object]:
    """Real tiny audio files (mp3/flac/m4a) generated by ffmpeg."""
    commands = {
        "mp3": ["-codec:a", "libmp3lame", "-b:a", "128k"],
        "flac": ["-codec:a", "flac"],
        "m4a": ["-codec:a", "aac"],
    }
    files: dict[str, object] = {}
    for name, codec_args in commands.items():
        out = tmp_path / f"sample.{name}"
        subprocess.run(
            ["ffmpeg", "-loglevel", "error", "-y", "-f", "lavfi",
             "-i", "sine=frequency=440:duration=0.4"]
            + codec_args + [str(out)],
            check=True,
            capture_output=True,
        )
        files[name] = out
    return files


@pytest.fixture
def mp3_stub(tmp_path):
    p = tmp_path / "stub.mp3"
    p.write_bytes(MP3_FRAME * 4)
    return p